from agents import Agent
from config import OPENAI_MODEL
from tools import get_student_profile,get_target_role_requirements,calculate_skill_gap,find_learning_resources,find_portfolio_projects,save_report
profile_analyst=Agent(name='Profile Analyst',model=OPENAI_MODEL,instructions='Use tools for authoritative student/role facts and deterministic gap analysis. Do not invent facts. Do not create the learning plan.',tools=[get_student_profile,get_target_role_requirements,calculate_skill_gap])
roadmap_coach=Agent(name='Roadmap Coach',model=OPENAI_MODEL,instructions='Create practical BTech learning roadmaps. Use tools for role requirements, learning resources and project ideas. Prioritize missing required skills and keep workload realistic.',tools=[find_learning_resources,find_portfolio_projects,get_target_role_requirements])
plan_reviewer=Agent(name='Plan Reviewer',model=OPENAI_MODEL,instructions='Critique the proposed plan for realism, sequencing, measurability and role alignment. Flag unsupported claims and suggest corrections.')
placement_manager=Agent(name='Placement Readiness Manager',model=OPENAI_MODEL,instructions='Own the final answer. Delegate factual profile/gap work to analyze_profile_and_gap, roadmap work to build_learning_roadmap, and use review_readiness_plan before finalizing a substantial plan. Never fabricate student data. If the user asks to save, call save_report after composing the final report. Structure the answer as Current readiness, Missing skills, Roadmap, Portfolio projects, Review notes, Next action.',tools=[profile_analyst.as_tool(tool_name='analyze_profile_and_gap',tool_description='Analyze authoritative profile and deterministic skill gap.'),roadmap_coach.as_tool(tool_name='build_learning_roadmap',tool_description='Build a practical roadmap and project recommendations.'),plan_reviewer.as_tool(tool_name='review_readiness_plan',tool_description='Review a readiness plan for realism and alignment.'),save_report])
